INSERT INTO product(name,slug,brand_id,sole_id,material_id,price,ole_price,weight,active,sold,image,description,short_description,meta_title,meta_description,created_at,updated_at) VALUES('[MẪU] Daily Walk 01','sports-di-bo-1',(SELECT record_id FROM catalog_release_item WHERE release_key='sports-20261024' AND kind='BRAND' AND ordinal=1),(SELECT record_id FROM catalog_release_item WHERE release_key='sports-20261024' AND kind='SOLE' AND ordinal=4),(SELECT record_id FROM catalog_release_item WHERE release_key='sports-20261024' AND kind='MATERIAL' AND ordinal=1),890000,990000,0.65,b'1',0,'/image/sports/di-bo.svg','<h2>Giày thể thao minh họa</h2><p>Catalog mới theo cấu trúc quản lý giày: thương hiệu, danh mục, đế, chất liệu, màu và size. Đây là dữ liệu DEMO, không phải mẫu giày thương mại được hãng xác nhận. Cần thay ảnh, thông số và tồn thực trước khi kinh doanh.</p>','Mẫu trình diễn, ảnh minh họa; không phải thông tin hàng hóa thật.','F6S SPORTS CATALOG 20261024','Mẫu giày thể thao trình diễn, không xác nhận hàng hóa thương mại.',NOW(6),NOW(6));
