-- F6S Sports / 02 CATALOG + LOCAL ADMIN
-- FRESH INSTALL ONLY. Use a new database; stop on any error. Never use mysql --force.
-- No OTP, service keys or VNPAY payment receipts are fabricated.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
USE f6s_shop_clean_demo;
-- Run once AFTER 01. Admin: admin@gmail.com / 123123; change before public use.
START TRANSACTION;
UPDATE product p JOIN catalog_release_item r ON r.record_id=p.id AND r.kind='PRODUCT' AND r.release_key='sports-20261024' SET p.code=CONCAT('F6S-SP',LPAD(CAST(p.id AS CHAR),GREATEST(6,CHAR_LENGTH(CAST(p.id AS CHAR))),'0'));
UPDATE product_detail d JOIN catalog_release_item r ON r.record_id=d.product_id AND r.kind='PRODUCT' AND r.release_key='sports-20261024' SET d.sku=CONCAT('F6S-SKU',LPAD(CAST(d.id AS CHAR),GREATEST(6,CHAR_LENGTH(CAST(d.id AS CHAR))),'0'));
UPDATE shoe_attribute SET code=CONCAT('F6S-',CASE kind WHEN 'BRAND' THEN 'TH' WHEN 'SOLE' THEN 'DE' ELSE 'CL' END,LPAD(CAST(id AS CHAR),GREATEST(6,CHAR_LENGTH(CAST(id AS CHAR))),'0')) WHERE code IS NULL;
COMMIT;
